// TH18 v1.00a Stage 1 W05 / MainSub05 reward formation, ranks 0..3.
// Source: st01.ecl.txt:1620-1668 MainSub05 scheduling; 117-134 Cir00bm/bp;
//         89-116 Cir00bfunc; 58-88 Cir00b_at. Source is an enmCreateF reward wave:
//         "skip when boss0 still exists" is fixed to the approved post-boss full wave.
// Shell: control enemy at (0,0) (no body), 120-frame opening buffer inside the phase
//        timer, real enemies keep their source hitbox/hurtbox and body-flap timing.
const TIME_LIMIT: int = 1800;   // phase timer = 120 buffer + 1680 source window
const SOURCE_LIMIT: int = 1680; // local estimate: schedule returns at 860, last charge clears ~1615
const OPENING_BUFFER: int = 120;

// TH18 type 5 Ball2. Source etSprite(0,5,4): shape 5, native color 4 kept.
const TH18_BALL2: int = 432;

// Source s:1627-1664 pops the current stage F0/F1 per creation; the enemies read the
// inherited pair at s:105. F1 is always 300, F0 is the per-plan target x.
sub emit(x: fx, y: fx, tx: fx) {
    _ = spawn_enemy(x, y, 120, 0, 0, 0, cir00b(tx, 300fx));
}

// s:58-88 Cir00b_at. RAND wait and all values are resolved per enemy before the burst.
async sub cir00b_fire() {
    var rank: int = global(GVAR_RANK);
    var delay: int = 30 + rand(200);          // E/N/!LO branch
    if rank == 2 { delay = 30 + rand(60); }   // H branch; Lunatic keeps the 200 range
    var shots: int = 0;
    var speed: fx = 1.0fx;
    if rank == 1 { shots = 1; speed = 1.3fx; }
    if rank == 2 { shots = 4; speed = 3.0fx; }
    if rank == 3 { shots = 6; speed = 4.0fx; }
    wait(delay);
    for i in 0..shots {
        // etAim(0,0): each etOn re-aims from the enemy's position at fire time.
        _ = fire(TH18_BALL2, 4, $self_x, $self_y, speed, aim_player(), none, none);
        wait(40);
    }
}

// s:89-116 Cir00bfunc, entered from the s:117-134 bp/bm wrappers. Drop lists and ANM
// sprite choices in those wrappers are the omitted reward/visual parts.
async sub cir00b(tx: fx, ty: fx) {
    // Source !L setDeath("DeadAttack1") and dropMain() are not simulated: the
    // invincible practice shell never kills these enemies, and the target has no
    // death-script hook (setDeath is not required for fixed-rank invuln cards).
    set_invuln(65535);                        // invincible practice shell
    set_enemy_flag(ENEMY_NO_BODY, 1);         // s:91 flagSet(3), the 0x2 body gate
    set_hurtbox(14fx);                        // s:95 setHurtbox(28,28): ordinary circle half-width
    set_hitbox(8fx);                          // s:96 setHitbox(16,16): ordinary circle half-width
    var u: fx = (rand(65536) - 32768) as fx / 32768; // RANDF2: signed [-1,1)
    var launch: angle = 270deg + ((546fx * u) as int as angle); // -pi/2 + RANDF2*0.05235988
    move_vel(0, launch, 0.6fx, EASE_LINEAR);  // s:97
    spawn cir00b_fire();                      // s:98 @Cir00b_at() async
    wait(70);                                 // s:99
    move_speed(20, 0fx, EASE_LINEAR);         // s:100 mode0 linear decel to 0
    wait(20);                                 // s:101 -> t=90
    set_enemy_flag(ENEMY_NO_BODY, 0);         // s:102 flagClear(3): body collision returns
    move_vel(0, aim_player(), 0fx, EASE_LINEAR); // s:103 freeze at the then-current player angle
    wait(80);                                 // s:104 -> t=170
    // s:105 getAngle(F2, FINAL_X, FINAL_Y, F0, F1): from own final position to (F0,F1).
    var charge: angle = atan2(ty - $self_y, tx - $self_x);
    move_vel(0, charge, 0fx, EASE_LINEAR);     // s:106
    move_vel(120, charge, 1.0fx, EASE_LINEAR); // s:107 mode0: speed 0 -> 1 over 120 frames
    wait(60);                                 // s:108
    loop { wait(1000); }                      // s:109-113; source delete() is unreachable
}

// s:1623-1667: wait100, then two identical rounds of 20 conditional plan creations.
async sub wave() {
    wait(OPENING_BUFFER);                     // shell buffer, outside the source schedule
    wait(100);                                // s:1623
    for round in 0..2 {                       // s:1624 $A = 2
        // s:1627-1636 F0=0, F1=300
        emit(0fx, 144fx, 0fx);
        wait(10);
        emit(-60fx, 160fx, 0fx); emit(60fx, 160fx, 0fx);
        wait(10);
        emit(-120fx, 192fx, 0fx); emit(120fx, 192fx, 0fx);
        wait(100);
        // s:1637-1646 F0=120
        emit(-160fx, 128fx, 120fx); emit(160fx, 128fx, 120fx);
        wait(10);
        emit(-120fx, 160fx, 120fx); emit(120fx, 160fx, 120fx);
        wait(10);
        emit(-30fx, 192fx, 120fx); emit(30fx, 192fx, 120fx);
        wait(100);
        // s:1647-1665
        emit(0fx, 144fx, 0fx);
        wait(10);
        emit(-40fx, 160fx, -120fx); emit(40fx, 160fx, -120fx);
        wait(10);
        emit(-80fx, 192fx, 120fx); emit(80fx, 192fx, 120fx);
        wait(10);
        emit(-120fx, 192fx, -120fx); emit(120fx, 192fx, -120fx);
        wait(10);
        emit(-160fx, 192fx, 120fx); emit(160fx, 192fx, 120fx);
        wait(100);                            // round total 380; schedule returns at 860
    }
}

// Synthetic shell enemy: hosts the phase event at (0,0) and never body-collides.
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hitbox(0fx);
    set_hurtbox(0fx);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, control);
    loop { wait(600); }
}
